public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int total = node._size;
    LinkedNode<byte[]> current = node._head;
    int remaining = total;
    while (current != null && remaining > 0) {
        byte[] buf = current._data;
        int len = Math.min(buf.length, remaining);
        out.write(buf, 0, len);
        remaining -= len;
        current = current._next;
    }
    return total;
}

