public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    if (desiredCapacity == 3) {
        return 3;
    }
    int start = (desiredCapacity % 2 == 0) ? desiredCapacity + 1 : desiredCapacity;
    int limit = (desiredCapacity >= 1000) ? (int) (desiredCapacity * 1.11) : Integer.MAX_VALUE;
    for (int n = start; n <= limit; n += 2) {
        if (isPrime(n)) {
            return n;
        }
    }
    // If no prime found within the 11% range, return the original capacity
    return desiredCapacity;
}

private static boolean isPrime(int n) {
    if (n < 2) {
        return false;
    }
    if (n % 2 == 0) {
        return n == 2;
    }
    int sqrt = (int) Math.sqrt(n);
    for (int i = 3; i <= sqrt; i += 2) {
        if (n % i == 0) {
            return false;
