protected int removeUnusedNodes(){
    if (root == null) return 0;
    int removed = 0;
    java.util.Deque<CategoryNode> stack = new java.util.ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()){
        CategoryNode current = stack.pop();
        java.util.Iterator<CategoryNode> it = current.getChildren().iterator();
        while (it.hasNext()){
            CategoryNode child = it.next();
            if (!child.isActive()){
                it.remove();
                removed++;
            } else {
                stack.push(child);
            }
        }
    }
    return removed;
}

