final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Find the offset of the CONSTANT_Utf8 entry in the class file buffer
    int offset = 0;
    for (int i = 1; i < constantPoolEntryIndex; i++) {
        int tag = classFileBuffer[offset] & 0xFF;
        offset++;
        switch (tag) {
            case 1: // CONSTANT_Utf8
                int len = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
                offset += 2 + len;
                break;
            case 3: // CONSTANT_Integer
            case 4: // CONSTANT_Float
                offset += 4;
                break;
            case 5: // CONSTANT_Long
            case 6: // CONSTANT_Double
                offset += 8;
                i++; // these take up two constant pool indices
                break;
            case 7: // CONSTANT_Class
            case 8: // CONSTANT_String
                offset += 2;
                break;
            case 9:  // CONSTANT_Fieldref
            case 10: // CONSTANT_Methodref
            case 11: // CONSTANT_InterfaceMethodref
            case 12: // CONSTANT_NameAndType
                offset += 4;
                break;
            default:
                throw new IllegalArgumentException("Invalid constant pool tag: " + tag);
        }
    }

    // Now at the target entry
    int tag = classFileBuffer[offset] & 0xFF;
    if (tag != 1) {
        throw new IllegalArgumentException("Expected CONSTANT_Utf8 at index " + constantPoolEntryIndex);
    }
    offset++;
    int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
    offset += 2;

    // Decode the UTF-8 bytes into the provided char buffer
    java.nio.ByteBuffer src = java.nio.ByteBuffer.wrap(classFileBuffer, offset, length);
    java.nio.CharBuffer dst = java.nio.CharBuffer.wrap(charBuffer);
    java.nio.charset.CharsetDecoder decoder = java.nio.charset.StandardCharsets.UTF_8.newDecoder();
    decoder.decode(src, dst, true);
    dst.flip();

    return new String(charBuffer, 0, dst.position());
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    // If the starting node is already the stop node, return immediately
    if (circ.node().equals(stop)) {
        return circ;
    }
    // Traverse the outer face until we hit the stop node or find a node that satisfies the predicate
    while (!circ.node().equals(stop)) {
        if (predicate.test(circ.node())) {
            return circ;
        }
        circ.next();
    }
    // We have reached the stop node; return the circulator positioned at it
    return circ;
}

