protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) return null;
    Set<E> remaining = new HashSet<>(tour);
    Iterator<E> it = remaining.iterator();
    E firstEdge = it.next();
    V startVertex = graph.getEdgeSource(firstEdge);
    V currentVertex = graph.getEdgeTarget(firstEdge);
    List<E> edgeList = new ArrayList<>();
    edgeList.add(firstEdge);
    remaining.remove(firstEdge);
    while (!remaining.isEmpty()) {
        boolean found = false;
        Iterator<E> iter = remaining.iterator();
        while (iter.hasNext()) {
            E e = iter.next();
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(currentVertex)) {
                currentVertex = tgt;
                edgeList.add(e);
                iter.remove();
                found = true;
                break;
            } else if (tgt.equals(currentVertex)) {
                currentVertex = src;
                edgeList.add(e);
                iter.remove();
                found = true;
                break;
            }
        }
        if (!found) break;
    }
    double weight = 0.0;
    for (E e : edgeList) weight += graph.getEdgeWeight(e);
    return new GraphWalk<>(graph, startVertex, currentVertex, edgeList, weight);
}

