public static String applyRelativePath(String path, String relativePath) {
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    boolean isAbsolute = path.startsWith("/");
    String[] baseParts = path.split("/");
    java.util.List<String> stack = new java.util.ArrayList<>();
    if (isAbsolute) {
        stack.add(""); // preserve leading slash
    }
    boolean pathEndsWithSlash = path.endsWith("/");
    int baseLen = baseParts.length;
    if (!pathEndsWithSlash && !relativePath.startsWith("./") && !relativePath.startsWith("../")) {
        baseLen--; // drop last component if path is a file
    }
    for (int i = 0; i < baseLen; i++) {
        if (!baseParts[i].isEmpty()) {
            stack.add(baseParts[i]);
        }
    }
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (stack.size() > 1) { // keep leading empty for root
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < stack.size(); i++) {
        String comp = stack.get(i);
        if (i == 0 && comp.isEmpty()) {
            sb.append("/");
            continue;
        }
        if (i > 0) sb.append("/");
        sb.append(comp);
    }
    String result = sb.toString();
    if (result.isEmpty()) {
        return ".";
    }
    return result;
}

